ALTER TABLE public.trip_network_settings ADD COLUMN pilot_safety_evidence jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE FUNCTION public.pilot_activation_checklist(_config jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;e jsonb;receivers uuid[];res jsonb;BEGIN IF NOT public.has_role(auth.uid(),'admin') AND NOT public.admin_can('requests','read') THEN RAISE EXCEPTION 'Pilot review permission required';END IF;SELECT coalesce(_config,pilot_config),pilot_safety_evidence INTO c,e FROM public.trip_network_settings WHERE id=true;c:=coalesce(c,'{}');e:=coalesce(e,'{}');SELECT array_agg(x::uuid) INTO receivers FROM jsonb_array_elements_text(coalesce(c->'receivers','[]')) x;
res:=jsonb_build_array(jsonb_build_object('label','Selected sender workspaces','ready',jsonb_array_length(coalesce(c->'senders','[]'))>0),jsonb_build_object('label','Selected receiving workspaces','ready',coalesce(cardinality(receivers),0)>0),jsonb_build_object('label','Service scope','ready',jsonb_array_length(coalesce(c->'services','[]'))>0),jsonb_build_object('label','Geography scope','ready',jsonb_array_length(coalesce(c->'cities','[]'))+jsonb_array_length(coalesce(c->'zips','[]'))+jsonb_array_length(coalesce(c->'counties','[]'))+jsonb_array_length(coalesce(c->'regions','[]'))>0),jsonb_build_object('label','Nearby opportunity consent','ready',coalesce(cardinality(receivers),0)>0 AND NOT EXISTS(SELECT 1 FROM unnest(receivers) r WHERE NOT EXISTS(SELECT 1 FROM public.provider_network_profiles WHERE workspace_id=r AND nearby_opt_in))),jsonb_build_object('label','Provider directory independence','ready',true),jsonb_build_object('label','Network entitlement mapping','ready',coalesce(cardinality(receivers),0)>0 AND NOT EXISTS(SELECT 1 FROM unnest(receivers) r WHERE NOT public.provider_network_entitled(r))),jsonb_build_object('label','Verification evidence','ready',coalesce(cardinality(receivers),0)>0 AND NOT EXISTS(SELECT 1 FROM unnest(receivers) r WHERE coalesce(public.provider_verification_evidence_internal(r)->>'level','none')='none')),jsonb_build_object('label','Vehicle and driver capability','ready',coalesce((e->>'capability_verified')::boolean,false)),jsonb_build_object('label','Offer screens','ready',true),jsonb_build_object('label','Pre-acceptance messaging','ready',true),jsonb_build_object('label','Acceptance-time recheck','ready',true),jsonb_build_object('label','Atomic assignment','ready',coalesce((e->>'atomic_rollback_verified')::boolean,false)),jsonb_build_object('label','Concurrency protection','ready',coalesce((e->>'concurrency_verified')::boolean,false)),jsonb_build_object('label','In-app notifications','ready',true),jsonb_build_object('label','External delivery intentionally off','ready',NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE enabled AND key IN ('managed_email','driver_schedule_email','sms','nearby_auto_waves','nearby_matching'))),jsonb_build_object('label','Stripe and settlement intentionally separate','ready',true),jsonb_build_object('label','Emergency stop','ready',true),jsonb_build_object('label','Audit history','ready',true));RETURN res;END $$;
CREATE FUNCTION public.scoped_matching_pilot() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;ws jsonb;BEGIN IF NOT public.admin_can('requests','read') THEN RAISE EXCEPTION 'Operations permission required';END IF;SELECT pilot_config INTO c FROM public.trip_network_settings WHERE id=true;SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'display_name',display_name,'mfn_id',mfn_id)),'[]') INTO ws FROM public.workspaces WHERE account_type='provider' AND status='active' AND NOT is_test_account AND public.admin_can_account(id);RETURN jsonb_build_object('enabled',coalesce((c->>'enabled')::boolean,false),'emergencyStop',coalesce((c->>'emergencyStop')::boolean,false),'level',CASE WHEN public.admin_can('requests','manage') THEN 'manage' ELSE 'read' END,'workspaces',ws,'services',coalesce(c->'services','[]'),'externalDelivery',false);END $$;
DO $change$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.save_matching_pilot(jsonb,text)'::regprocedure) INTO f;f:=replace(f,'UPDATE public.trip_network_settings SET pilot_config=_config', 'IF coalesce((_config->>''enabled'')::boolean,false) AND EXISTS(SELECT 1 FROM jsonb_array_elements(public.pilot_activation_checklist(_config)) x WHERE x->>''ready'' IS DISTINCT FROM ''true'') THEN RAISE EXCEPTION ''Required pilot safety checks are not ready'';END IF; UPDATE public.trip_network_settings SET pilot_config=_config');EXECUTE f;END $change$;
CREATE FUNCTION public.customer_selected_request_export(_ids uuid[],_format text) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n integer;res jsonb;BEGIN IF auth.uid() IS NULL OR cardinality(_ids) NOT BETWEEN 1 AND 500 OR _format NOT IN ('csv','xlsx','pdf') THEN RAISE EXCEPTION 'Invalid selection';END IF;
SELECT count(*),jsonb_agg(jsonb_build_object('reference',r.mfn_id,'date',r.pickup_date,'time',r.pickup_time,'pickup',r.pickup_city,'destination',r.dropoff_city,'service',r.transport_type,'status',CASE WHEN r.status IN ('canceled','cancelled','denied','declined') THEN 'Provider unavailable' WHEN r.assigned_provider_id IS NOT NULL THEN 'Provider selected' ELSE coalesce(r.provider_selection_status,'Under Review') END) ORDER BY r.pickup_date,r.pickup_time) INTO n,res FROM public.ride_requests r WHERE r.id=ANY(_ids) AND NOT r.is_test AND (public.patient_request_access(r.id) OR EXISTS(SELECT 1 FROM public.workspaces w JOIN public.workspace_members m ON m.workspace_id=w.id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE w.id=r.workspace_id AND w.account_type IN ('facility','hospital') AND w.status='active' AND NOT w.is_test_account AND r.saved_patient_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.saved_patients s WHERE s.id=r.saved_patient_id AND s.workspace_id=w.id) AND m.user_id=auth.uid() AND m.removed_at IS NULL AND NOT m.is_contractor AND (m.role IN ('owner','admin') OR m.can_view_workspace_requests) AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL));
IF n<>(SELECT count(DISTINCT x) FROM unnest(_ids) x) THEN RAISE EXCEPTION 'Some selected records unavailable';END IF;PERFORM public.record_selected_export(_ids,ARRAY['reference','date','time','pickup','destination','service','status'],_format);RETURN coalesce(res,'[]');END $$;
REVOKE ALL ON FUNCTION public.pilot_activation_checklist(jsonb),public.scoped_matching_pilot(),public.customer_selected_request_export(uuid[],text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.pilot_activation_checklist(jsonb),public.scoped_matching_pilot(),public.customer_selected_request_export(uuid[],text) TO authenticated;